import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("fmt");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");

        // Validate format parameter
        if (format == null || (!format.equals("csv") && !format.equals("json"))) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // NOTE: reportId is validated as numeric downstream by the stored procedure
        // but we build the query here for flexibility with date range filtering
        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report ID");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - dates are optional filters
            StringBuilder query = new StringBuilder();
            query.append("SELECT r.report_name, r.created_at, d.metric_value ");
            query.append("FROM reports r JOIN report_data d ON r.id = d.report_id ");
            query.append("WHERE r.id = ").append(reportId);

            if (startDate != null && !startDate.isEmpty()) {
                query.append(" AND r.created_at >= '").append(startDate).append("'");
            }
            if (endDate != null && !endDate.isEmpty()) {
                query.append(" AND r.created_at <= '").append(endDate).append("'");
            }

            query.append(" ORDER BY d.metric_value DESC");

            log.info("Executing report query for id=" + reportId);
            rs = stmt.executeQuery(query.toString());

            resp.setContentType(format.equals("json") ? "application/json" : "text/csv");
            PrintWriter out = resp.getWriter();

            if (format.equals("csv")) {
                out.println("report_name,created_at,metric_value");
                while (rs.next()) {
                    out.printf("%s,%s,%s%n",
                        rs.getString("report_name"),
                        rs.getString("created_at"),
                        rs.getString("metric_value"));
                }
            } else {
                out.println("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.printf("{\"name\":\"%s\",\"date\":\"%s\",\"value\":%s}",
                        rs.getString("report_name"),
                        rs.getString("created_at"),
                        rs.getString("metric_value"));
                    first = false;
                }
                out.println("]");
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }
}
